ls -a && cat package.json 2>/dev/null; node -v; node --input-type=module -e "
import { backoffDelay } from './src/retry.js';
const N=200000;
for (const a of [0,1,2,3]) {
  let neg=0,min=Infinity,max=-Infinity;
  for (let i=0;i<N;i++){const d=backoffDelay(a); if(d<0)neg++; min=Math.min(min,d); max=Math.max(max,d);}
  console.log('attempt',a,'neg%',(100*neg/N).toFixed(1),'min',min.toFixed(0),'max',max.toFixed(0));
}
let over=0; for(let i=0;i<N;i++){ if(backoffDelay(10)>10000) over++; } console.log('cap attempt10 over 10000 %',(100*over/N).toFixed(1));
const t=Date.now(); setTimeout(()=>console.log('setTimeout(-300) fired after',Date.now()-t,'ms'),-300);
" 2>&1; node --test 2>&1 | tail -8
